head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16509";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — editAvailYn, regYn

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16509.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_46_txt", fn: function(){ return ((dma_educationList.get("roomTpCd") ?? (() => { throw new Error("unresolved:" + "educationList.roomTpCd"); })()) === '1'); } }, { id: "c_otherwise_47", fn: function(){ return (!(((dma_educationList.get("roomTpCd") ?? (() => { throw new Error("unresolved:" + "educationList.roomTpCd"); })()) === '1'))); } }, { id: "c_when_71_txt", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_otherwise_72", fn: function(){ return (!(((dma_pageContext.get("editAvailYn") ?? "") !== 'N'))); } }, { id: "c_when_88", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_otherwise_90", fn: function(){ return (!(((dma_pageContext.get("editAvailYn") ?? "") !== 'N'))); } }, { id: "if_editAvailYn", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_when_84", fn: function(){ return ((dma_educationList.get("submitYn") ?? (() => { throw new Error("unresolved:" + "educationList.submitYn"); })()) === 'Y'); } }, { id: "c_when_105", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_otherwise_107", fn: function(){ return (!(((dma_pageContext.get("editAvailYn") ?? "") !== 'N'))); } }, { id: "if_editAvailYn_2", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_when_101", fn: function(){ return ((dma_educationList.get("submitYn") ?? (() => { throw new Error("unresolved:" + "educationList.submitYn"); })()) === 'N'); } }, { id: "c_otherwise_120", fn: function(){ return (!(((dma_educationList.get("submitYn") ?? (() => { throw new Error("unresolved:" + "educationList.submitYn"); })()) === 'Y') || ((dma_educationList.get("submitYn") ?? (() => { throw new Error("unresolved:" + "educationList.submitYn"); })()) === 'N'))); } }, { id: "img_129", fn: function(){ return ((dma_pageContext.get("regYn") ?? "") === '1'); } }, { id: "c_otherwise_130", fn: function(){ return (!(((dma_pageContext.get("regYn") ?? "") === '1'))); } }, { id: "img_137", fn: function(){ return ((dma_pageContext.get("regYn") ?? "") === '1'); } }, { id: "c_otherwise_138", fn: function(){ return (!(((dma_pageContext.get("regYn") ?? "") === '1'))); } }, { id: "img_143", fn: function(){ return ((dma_pageContext.get("regYn") ?? "") === '1'); } }, { id: "c_otherwise_144", fn: function(){ return (!(((dma_pageContext.get("regYn") ?? "") === '1'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

